<script setup>import AdminShell from '../../components/AdminShell.vue';import StatusBadge from '../../components/StatusBadge.vue';import {documents} from '../../api/mock';</script>
<template><AdminShell><template #title>技术文档</template><div class="heading"><div><p>CONTROLLED DOCUMENTS</p><h1>技术文档中心</h1><span>图纸、规范与验证文件的统一版本受控</span></div><button class="btn primary">＋ 上传文档</button></div><section class="panel"><div class="toolbar"><div class="tabs"><button class="active">全部文档</button><button>图纸</button><button>规范</button><button>验证文件</button></div><label>⌕ <input placeholder="搜索文档"/></label></div><table><thead><tr><th>文档编号 / 名称</th><th>分类</th><th>版本</th><th>关联产品</th><th>负责人</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="d in documents" :key="d.no"><td><b>{{d.no}}</b><small>{{d.name}}</small></td><td>{{d.type}}</td><td>{{d.version}}</td><td>PRD-{{d.no.includes('GW')?'GW100':'SV750'}}</td><td>{{d.owner}}</td><td><StatusBadge :value="d.status"/></td><td>{{d.updated}}</td></tr></tbody></table></section></AdminShell></template>
